#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn terminal_themes_are_parseable_and_nonempty() {
        assert!(TERMINAL_THEMES.len() > 400);
        for t in TERMINAL_THEMES {
            assert!(!t.name.is_empty());
        }
    }
    #[test]
    fn palette_has_16_entries() {
        for t in TERMINAL_THEMES {
            assert_eq!(t.palette.len(), 16);
        }
    }
}
